#include "AHEFonts.h"
#include "AHEBrandData.h"   // generated by juce_add_binary_data (target AHEBrandData)

namespace ahe::fonts
{
    namespace
    {
        juce::Typeface::Ptr load (const char* data, int size)
        {
            return juce::Typeface::createSystemTypefaceFor (data, (size_t) size);
        }
    }

    // Loaded once on first use and shared by every plug-in instance.
    juce::Typeface::Ptr uiRegular()
    {
        static auto t = load (AHEBrandData::InterRegular_ttf, AHEBrandData::InterRegular_ttfSize);
        return t;
    }

    juce::Typeface::Ptr uiSemiBold()
    {
        static auto t = load (AHEBrandData::InterSemiBold_ttf, AHEBrandData::InterSemiBold_ttfSize);
        return t;
    }

    juce::Typeface::Ptr display()
    {
        static auto t = load (AHEBrandData::BarlowCondensedExtraBoldItalic_ttf,
                              AHEBrandData::BarlowCondensedExtraBoldItalic_ttfSize);
        return t;
    }
}
